import sys

MOD = 1000000007

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, h = data[0], data[1]
    a = data[2:2+n]

    for x in a:
        if x > h:
            print(0)
            return

    # dp[j] = number of ways with j currently open segments
    dp = [0] * (n + 2)
    dp[0] = 1

    prev = h
    for i in range(n):
        cur = a[i]
        ndp = [0] * (n + 2)

        if cur == prev:
            # can keep same number of open segments, or close one and open one
            for j in range(n + 1):
                if dp[j] == 0:
                    continue
                # no change
                ndp[j] = (ndp[j] + dp[j]) % MOD
                # close one and open one (requires j >= 1)
                if j >= 1:
                    ndp[j] = (ndp[j] + dp[j] * j) % MOD
        elif cur == prev - 1:
            # must open one new segment
            for j in range(n + 1):
                if dp[j] == 0:
                    continue
                ndp[j + 1] = (ndp[j + 1] + dp[j]) % MOD
        elif cur == prev + 1:
            # must close one segment
            for j in range(1, n + 1):
                if dp[j] == 0:
                    continue
                ndp[j - 1] = (ndp[j - 1] + dp[j] * j) % MOD
        else:
            print(0)
            return

        dp = ndp
        prev = cur

    # after last element, must close all open segments
    ans = 0
    for j in range(n + 1):
        if dp[j] == 0:
            continue
        # close all j segments in some order: j!
        ways = dp[j]
        for k in range(2, j + 1):
            ways = ways * k % MOD
        ans = (ans + ways) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()
